import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Änderungshistorie","description":"","frontmatter":{"title":"Änderungshistorie","covers":{"screens":["SCR-026"],"stories":["US-098"]}},"headers":[],"relativePath":"de/usage/change-history.md","filePath":"de/usage/change-history.md"}`),a={name:`de/usage/change-history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="anderungshistorie" tabindex="-1">Änderungshistorie <a class="header-anchor" href="#anderungshistorie" aria-label="Permalink to “Änderungshistorie”">​</a></h1><p>Jede Änderung an einer Entität erzeugt eine neue Version. Die Seite <em>Änderungshistorie</em> zeigt, wer eine Entität wann geändert hat und welche Felder jede Version geändert hat. Du brauchst die Berechtigung <code>entity:read</code>; die Rollen <code>viewer</code>, <code>analyst</code> und <code>enterprise-architect</code> haben sie.</p><h2 id="die-anderungshistorie-offnen" tabindex="-1">Die Änderungshistorie öffnen <a class="header-anchor" href="#die-anderungshistorie-offnen" aria-label="Permalink to “Die Änderungshistorie öffnen”">​</a></h2><p>Wähle in einem <a href="./catalogs">Katalog</a> oder in einem Katalog des <a href="./portal">Portals</a> in der Zeile einer Entität <em>Historie</em>. Die Seite öffnet sich mit den Versionen der Entität, die neueste zuerst. <em>Zurück zum Katalog</em> führt zum Katalog, von dem du gekommen bist, auf derselben Seite und mit derselben Sortierung.</p><h2 id="die-eintrage-lesen" tabindex="-1">Die Einträge lesen <a class="header-anchor" href="#die-eintrage-lesen" aria-label="Permalink to “Die Einträge lesen”">​</a></h2><p>Jeder Eintrag zeigt:</p><ul><li>die <strong>Versionsnummer</strong>, bei der ersten Version <em>Erstellt</em>;</li><li>die <strong>Zeit</strong> der Änderung in deiner lokalen Zeitzone;</li><li>die <strong>Person</strong>, die die Änderung gemacht hat;</li><li>die <strong>geänderten Felder</strong>: Systemfelder wie <em>Name</em> oder <em>Beschreibung</em> und die Eigenschaften mit ihrer Beschriftung.</li></ul><p>Die Einträge nennen die geänderten Felder, nicht ihre Werte. Die Werte und der Vergleich zweier Versionen folgen in einem späteren Release.</p><p>Eine Entität, die nach ihrer Erstellung nie geändert wurde, zeigt <em>Keine Änderungen seit der Erstellung. Erstellt am {Datum} von {Person}.</em></p><h2 id="eingeschrankte-felder" tabindex="-1">Eingeschränkte Felder <a class="header-anchor" href="#eingeschrankte-felder" aria-label="Permalink to “Eingeschränkte Felder”">​</a></h2><p>Eine Eigenschaft, die du nach der <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a> nicht lesen darfst, zeigt nie ihren Wert. Je nach den Einstellungen deiner Rollen für den Entitätstyp erscheint das Feld mit dem Badge <em>Eingeschränkt</em>, oder es fehlt. Fehlen alle Felder einer Version, bleibt die Version ohne Felder in der Liste, damit die Nummerierung keine Lücken hat.</p><h2 id="filtern-und-mehr-laden" tabindex="-1">Filtern und mehr laden <a class="header-anchor" href="#filtern-und-mehr-laden" aria-label="Permalink to “Filtern und mehr laden”">​</a></h2><ul><li><strong>Person:</strong> Wähle eine Person, um nur ihre Versionen zu sehen. Die Liste bietet alle an, die die Entität geändert haben.</li><li><strong>Zeitraum:</strong> Wähle ein Start- und ein Enddatum. Beide Tage zählen ganz: Eine Version am Start- oder am Enddatum wird angezeigt.</li></ul><p>Die Seite zeigt zuerst 50 Versionen. <em>Mehr laden</em> fügt die nächsten 50 hinzu.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><p><code>GET /entities/{id}/history</code> liefert die Versionen, die neueste zuerst, mit <code>from</code> und <code>to</code> (Zeitpunkte, einschliesslich), <code>actorId</code>, <code>page</code>, <code>pageSize</code> (1 bis 200, Standard 50) und <code>cursor</code> (der <code>nextCursor</code> der vorigen Seite, gesendet mit <code>page</code> + 1). Die Antwort nennt die Erstellung in <code>created</code> und alle Personen, die eine Version gemacht haben, in <code>actors</code>, unabhängig von den Filtern. Ein Start nach dem Ende wird mit 400 und <code>from</code> beantwortet, eine unbekannte Entität mit 404.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};